{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("b", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_and_ignores_empty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"a": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (9, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_fields_whitespace_comments_and_blank_lines():
    lines = ["\n", "  # a comment, with commas\n", "  a , -2 , 1  ", "b, 3, 0", "c,4,  "]
    assert parse_transcript_log(lines) == [event("a", -2, True), event("b", 3, False), event("c", 4, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match="line 4"):
        parse_transcript_log(["", " # skipped", "ok,1,0", bad_line])


def test_dedupe_duplicate_ids_keep_last_and_sort_by_day_then_id():
    first = event("a", 9, True)
    last = event("a", 2, False)
    events = [first, event("z", 1, True), event("b", 2, True), last]
    assert dedupe_transcripts(events) == [events[1], last, events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_outside_ignored():
    events = [event("a", 1, True), event("b", 3, True), event("c", 3, True),
              event("d", 2, False), event("e", 2, None), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 2, 0]
    assert daily_flag_counts(events, 3, 3) == [2]
    assert daily_flag_counts(events, 4, 3) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_summary_uses_calendar_days_pooled_rate_and_nonempty_group_count():
    groups = {
        "a": [event("a", 1, True), event("b", 10, False), event("c", 10, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary(groups, 10)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    result = flag_rate_by_group({"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]})
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_and_negative_counts():
    assert longest_flag_streak([1, 2, 0, 4, -1, 1, 1, 1]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
